"""Corpus for the differential Painless harness: (name, context, source, params, document)."""
CASES = []
_n = {}


def _add(cat, ctx, src, params=None, doc=None):
    _n[cat] = _n.get(cat, 0) + 1
    CASES.append((f"{cat}_{_n[cat]}", ctx, src, params, doc))


def pt(cat, *srcs):
    for s in srcs:
        _add(cat, "painless_test", s)


def cx(cat, ctx, *srcs, params=None, doc=None):
    for s in srcs:
        _add(cat, ctx, s, params, doc)


